import{c as s,ah as a,L as e,O as h}from"./chunks/framework.YKVbmyBD.js";const g=JSON.parse('{"title":"安装 Nvidia 驱动","description":"","frontmatter":{},"headers":[],"relativePath":"fovlin-notes/linux-guide/configure-system/nvidia-driver.md","filePath":"fovlin-notes/linux-guide/configure-system/nvidia-driver.md"}'),t={name:"fovlin-notes/linux-guide/configure-system/nvidia-driver.md"};function l(n,i,p,k,d,r){return a(),e("div",null,[...i[0]||(i[0]=[h('<h1 id="安装-nvidia-驱动" tabindex="-1">安装 Nvidia 驱动 <a class="header-anchor" href="#安装-nvidia-驱动" aria-label="Permalink to “安装 Nvidia 驱动”">​</a></h1><p>对于不同的 Linux 发行版，安装方式略不相同。</p><h2 id="ubuntu" tabindex="-1">Ubuntu <a class="header-anchor" href="#ubuntu" aria-label="Permalink to “Ubuntu”">​</a></h2><p><strong>方法一：下载官方仓库开源驱动</strong></p><p>在附加驱动应用程序中直接下载，或者使用 ubuntu-driver autoinstall 命令进行安装。</p><p><strong>方法二：安装 NVIDIA 官方闭源驱动</strong></p><p>前往 Nvidia 官网下载对应的驱动安装文件，通常为 <code>.run</code> 文件，赋予权限并以 root 身份运行此文件。</p><p>在开始运行之前，首先安装必要的软件包。</p><ul><li>内核头文件</li></ul><p>此包在仓库内的名称为 <code>linux-headers-你的内核版本</code>，若未安装此包直接运行驱动安装程序，会返回 <code>无法发现内核源文件</code> 的报错。</p><p>使用 <code>uname -r</code> 命令可以查询内核版本号，同时我们可以使用 <code>$(command)</code> 的方式将输出转换为字符串，故安装内核头文件可以使用以下方法：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> linux-headers-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><ul><li>gcc 编译器</li></ul><p>安装 gcc，但更推荐安装编译包集合：<code>build-essential</code></p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gcc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # build-essential</span></span></code></pre></div><p>随后赋予安装程序权限，运行安装程序。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 711</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NVIDIA-Linux-x86_64-580.142.run</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./NVIDIA-Linux-x86_64-580.142.run</span></span></code></pre></div><h2 id="fedora" tabindex="-1">Fedora <a class="header-anchor" href="#fedora" aria-label="Permalink to “Fedora”">​</a></h2><p><strong>方法一：安装官方 rpm 仓库内驱动</strong></p><p>参考：<a href="https://docs.fedoraproject.org/en-US/gaming/drivers/" target="_blank" rel="noreferrer">Fedodra 官方文档</a></p><p>启用 rpm 仓库：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://mirrors.rpmfusion.org/free/fedora/rpmfusion-free-release-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %fedora</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.noarch.rpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://mirrors.rpmfusion.org/nonfree/fedora/rpmfusion-nonfree-release-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> %fedora</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.noarch.rpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p>安装 nvidia 驱动：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> akmod-nvidia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span></span></code></pre></div><p>随后使用 <code>reboot</code> 重启系统即可。</p><p><strong>方法二：安装 NVIDIA 官方闭源驱动</strong></p><p>前往 Nvidia 官网下载对应的驱动安装文件，通常为 <code>.run</code> 文件，赋予权限并以 root 身份运行此文件。</p><p>在开始运行之前，首先安装必要的软件包。</p><ul><li>内核头文件</li></ul><p>此包在仓库内的名称为 <code>kernel-headers</code>，若未安装此包直接运行驱动安装程序，会返回 <code>无法发现内核源文件</code> 的报错。</p><p>此软件包默认会安装当前系统支持的最新内核版本的头文件，故需要先使用 <code>sudo dnf update</code> 将内核版本升级到此系统支持的最新版本。</p><p>若上一步升级了内核版本，则需要重启系统。</p><p>随后安装内核头文件。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kernel-headers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kernel-devel</span></span></code></pre></div><ul><li>gcc 编译器</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dnf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gcc</span></span></code></pre></div><p>随后赋予安装程序权限，运行安装程序。</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 711</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NVIDIA-Linux-x86_64-580.142.run</span></span></code></pre></div><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./NVIDIA-Linux-x86_64-580.142.run</span></span></code></pre></div><p>运行完成后，重启系统。</p><h2 id="arch-linux" tabindex="-1">Arch Linux <a class="header-anchor" href="#arch-linux" aria-label="Permalink to “Arch Linux”">​</a></h2><p>官方仓库提供 <code>nvidia-open</code>、<code>nvidia-open-dkms</code>包，推荐使用后者，dkms 会在内核更新后自动触发重新编译以适应新内核</p>',43)])])}const c=s(t,[["render",l]]);export{g as __pageData,c as default};
